shell_commands:
node -e '
const {execSync} = require("node:child_process");
const lock = JSON.parse(execSync("git show origin/main:package-lock.json", {encoding: "utf8"}));
for (const k of ["node_modules/ajv", "node_modules/fast-deep-equal", "node_modules/fast-json-stable-stringify", "node_modules/json-schema-traverse", "node_modules/uri-js", "node_modules/punycode"]) {
  console.log(k, JSON.stringify(lock.packages[k], null, 2));
}
'

node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({allErrors: true, format: false, unknownFormats: 'ignore'});
const validate = ajv.compile({type: 'object', properties: {location: {type: 'string'}}, required: ['location']});
console.log('empty:', validate({}), validate.errors);
console.log('wrong type:', validate({location: 123}), validate.errors);
try {
  ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
} catch (e) {
  console.log('invalid schema threw:', e.message);
}
"

node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({allErrors: true, format: false, unknownFormats: 'ignore'});
const validate = ajv.compile({
  type: 'object',
  properties: {
    unit: {type: 'string', enum: ['celsius', 'fahrenheit']},
    nested: {type: 'object', properties: {code: {type: 'number'}}, required: ['code']}
  },
  required: ['unit']
});
console.log('bad enum:', validate({unit: 'secret-value', nested: {code: 'secret-code'}}), validate.errors);
"

node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({allErrors: true, format: false, unknownFormats: 'ignore'});
const validate = ajv.compile({
  type: 'object',
  properties: {
    location: {type: 'string'},
    unit: {type: 'string', enum: ['celsius', 'fahrenheit']},
    nested: {type: 'object', properties: {code: {type: 'number'}}, required: ['code']}
  },
  required: ['location']
});
validate({});
console.log('missing required:', ajv.errorsText(validate.errors));
validate({location: 123, unit: 'secret-value', nested: {code: 'secret-code'}});
console.log('wrong types:', ajv.errorsText(validate.errors));
"
